CREATE TABLE IF NOT EXISTS {schema}.fills (fill_id {uuid} PRIMARY KEY, market_name {keyed} NOT NULL REFERENCES {schema}.markets(name), sell_order_id {uuid} NOT NULL REFERENCES {schema}.sell_orders(id), buy_order_id {uuid} NOT NULL REFERENCES {schema}.buy_orders(id), quantity {integer} NOT NULL CHECK (quantity > 0), unit_price {numeric} NOT NULL CHECK (unit_price > 0), item_blob {blob} NOT NULL, remaining_item_blob {blob} NOT NULL, status {status} NOT NULL CHECK (status IN ('RESERVED', 'MONEY_SETTLED', 'DELIVERED', 'VOIDED')), created_at {ts} NOT NULL{defaultNow})
